data.example_webhook_code:
const express = require('express')
const crypto = require('crypto')
const app = express()

app.use(express.json())

const WEBHOOK_SECRET = 'tu_signing_secret'

app.post('/webhook', (req, res) => {
  // 1. Verificar firma HMAC
  const signature = req.headers['x-webhook-signature']
  const hmac = crypto.createHmac('sha256', WEBHOOK_SECRET)
  hmac.update(JSON.stringify(req.body))
  const expected = hmac.digest('hex')

  if (!crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) {
    return res.status(401).send('Firma inválida')
  }

  // 2. Procesar según el tipo de evento
  const { event, data } = req.body

  switch (event) {
    case 'message.incoming':
      console.log(`Mensaje de ${data.contact.name}: ${data.content}`)
      // Aquí puedes responder automáticamente, guardar en DB, etc.
      break
    case 'message.sent':
      console.log(`Mensaje enviado: ${data.message_id}`)
      break
    case 'device.disconnected':
      console.log('⚠️ Dispositivo desconectado, enviar alerta')
      break
  }

  res.status(200).send('OK')
})

app.listen(3000, () => console.log('Webhook server en puerto 3000'))
